function esc(s){return String(s).replace(/[&<>"]/g,function(c){return{"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]})}
function nm(s){return s.split("{имя}").join(esc(S.name||(lang==="ru"?"ребёнок":"бала")))}
function txt(id,side){var q=Q[id],y=young();
  if(id==="q9"){if(S.goal===3) return side==="c"?(y?P4_Y:P4).c[lang]:null; if(S.goal===2&&side==="c") return (y?Q9_SUBJ_Y:Q9_SUBJ)[lang];}
  if(side==="c"&&y&&YC[id]) return YC[id].c[lang];
  return q[side][lang];}
function kidOpts(id){var y=young(); if(id==="q9"&&S.goal===3) return (y?P4_Y:P4).o[lang]; if(y&&YC[id]) return YC[id].o[lang]; return opts(id);}
function frameText(id){var f=Q[id].f[lang]; if(!Q[id].c) return f; return f.replace(Q[id].c[lang],txt(id,"c"));}
