/* ===== РАСЧЁТ ===== */
function isSchool(){return S.goal===0||S.goal===1}
function cardFor(id){
  var p=S.bets[id],c=S.kid[id]; if(c==null||c<0||p==null) return null;
  var key=id+":"+c, sch=(id!=="q9")||isSchool();
  if(p===-1){ if(Q[id].mark.indexOf(c)<0) return null; if(id==="q9"&&c===3&&!sch) return null; return OS[key]?{id:id,v:OS[key],src:"os"}:null; }
  var d=Q[id].ord?Math.abs(p-c):(p===c?0:9); if(d<2) return null;
  var vc=sch?VC[key]:null;
  if(vc) return {id:id,v:vc,src:"vc",miss:vc.miss&&vc.miss[p]};
  return {id:id,v:{t:Q[id].topic,b:{ru:[CARDS[id].ru[0]],kz:[CARDS[id].kz[0]]},a:CARDS[id].ru[1]?{ru:CARDS[id].ru[1],kz:CARDS[id].kz[1]}:null},src:"draft"};
}
function calc(){
  var res={hit:0,y:0,dots:[],conf:[],near:null,cards:[],flags:0,protocol:false,conflict:false};
  ORDER.forEach(function(id){
    var q=Q[id],p=S.bets[id],c=S.kid[id]; Q[id]._d=null;
    if(q.mark.indexOf(c)>-1) res.flags++;
    if(p<0||c<0||p==null||c==null) return;
    var d=q.ord?Math.abs(p-c):(p===c?0:9); Q[id]._d=d;
    if(q.score){res.y++; if(d===0)res.hit++; res.dots.push(d===0?"h":d===1?"n":"x");}
    if(d===0&&CONFIRM[id]&&!(id==="q7"&&c>1)) res.conf.push(id);
    if(d===1&&!res.near) res.near=id;
  });
  if(S.grade!=null&&S.grade<=4){res.flags=["q4","q5","q7"].filter(function(id){return Q[id].mark.indexOf(S.kid[id])>-1}).length; if(res.flags>=2) res.protocol=true;}
  else if(res.flags>=3) res.protocol=true;
  if(DICT.test(S.free)) res.protocol=true;
  if(S.kid.q9===3&&isSchool()) res.conflict=true;
  var chain=CHAIN.slice(); if(S.goal===3){chain.shift();chain.push(["q9"]);}
  chain.forEach(function(g){ if(res.cards.length>=3)return;
    for(var j=0;j<g.length;j++){var cf=cardFor(g[j]); if(cf){res.cards.push(cf);break;}}
  });
  return res;
}

